QString number(const IntegerController& c,double x){return QString::fromStdString(core::NumberFormatter(c.input().document()->inputFormat).format(x));}
QString nodeState(integer::NodeState s){switch(s){case integer::NodeState::AwaitingBranch:return "Awaiting branching choice";case integer::NodeState::Infeasible:return "Infeasible";case integer::NodeState::BoundPruned:return "Bound pruned";case integer::NodeState::IntegerSolution:return "Integer solution";case integer::NodeState::Branched:return "Branched";case integer::NodeState::Unbounded:return "Unbounded relaxation";}return {};}
QString branchText(const IntegerController& c,const integer::BranchConstraint& branch){return QStringLiteral("x%1 %2 %3").arg(branch.variable+1).arg(branch.relation==lp::Relation::LessEqual?"<=":">=",number(c,branch.bound));}
QString status(const IntegerController& c){if(!c.result())return "No current solution";const auto& r=*c.result();QString text;if(c.guided() && !c.guided()->finished()){text=c.guided()->awaitingBranch()?"User-guided B&B: choose a fractional integer branching variable":"User-guided B&B: choose a pending subproblem";if(r.objective)text+="; incumbent objective = "+number(c,*r.objective);return text;}switch(r.status){case integer::Status::Optimal:text="Integer optimum certified";break;case integer::Status::Infeasible:text="No feasible integer solution";break;case integer::Status::NodeLimit:text="Search stopped at node limit; optimality unproved";break;case integer::Status::ModelLimit:text="Search stopped at internal branch row limit; optimality unproved";break;case integer::Status::UnboundedRelaxation:text="Unbounded LP relaxation; integer conclusion unproved";break;}if(r.objective)text+="; incumbent objective = "+number(c,*r.objective);return text;}
