void menu(ApplicationShell& shell,QMenuBar& bar,bool editing){auto& c=integerController(shell);auto* file=bar.addMenu("File");file->addAction("Open",&shell,[&c]{c.requestOpen();});file->addAction("Save As",&shell,[&c]{c.requestSave();});if(!editing)return;auto* edit=bar.addMenu("EditGrid");auto* undo=edit->addAction("Undo Last Insert, Paste, Or Delete",&shell,[&c]{c.undo();});undo->setShortcut(QKeySequence("Ctrl+U"));auto* copy=edit->addAction("Copy Column or Row",&shell,[&c]{c.copySelection();});copy->setShortcut(QKeySequence("Ctrl+C"));auto* paste=edit->addAction("Paste on Column or Row",&shell,[&c]{c.pasteSelection();});paste->setShortcut(QKeySequence("Ctrl+P"));auto* remove=edit->addAction("Delete Column or Row",&shell,[&c]{c.deleteSelection();});remove->setShortcut(QKeySequence("Ctrl+D"));auto* insert=edit->addAction("Insert Column or Row",&shell,[&c]{c.insertSelection();});insert->setShortcut(QKeySequence("Ctrl+I"));const auto refresh=[&c,undo,copy,paste,remove,insert]{undo->setEnabled(!c.readOnly() && c.hasUndo());copy->setEnabled(c.input().canCopy());paste->setEnabled(!c.readOnly() && c.input().canPaste());remove->setEnabled(!c.readOnly() && c.input().canCopy());insert->setEnabled(remove->isEnabled());};QObject::connect(&c,&IntegerController::changed,edit,refresh);QObject::connect(&c.input(),&LpInputController::selectionChanged,edit,refresh);refresh();}
