ModuleDescriptor integerModule(){ModuleDescriptor module{"integer","Integer programming","integer/input",{}, {}};module.beforeLeave=[](ApplicationShell& shell,const QString& from,const QString& to){return !from.startsWith("integer/") || to.startsWith("integer/") || integerController(shell).allowLeave();};module.screens.append({"integer/input","INTEGER PROGRAMMING",inputScreen,[](ApplicationShell& shell,QMenuBar& bar){menu(shell,bar,true);}});module.screens.append({"integer/result","INTEGER PROGRAMMING",resultScreen,[](ApplicationShell& shell,QMenuBar& bar){menu(shell,bar,false);}});return module;}
bool printInteger(QPrinter& printer,const IntegerController& c,const QFont& font){if(!c.result() || !c.input().document())return false;try{QString html="<h1>Integer programming</h1>";const auto line=[&](const QString& text){html+="<p>"+text.toHtmlEscaped()+"</p>";};const auto& p=c.input().document()->problem;line(legacyText(p.title));line(status(c));for(std::size_t j=0;j<c.result()->values.size();++j)line(legacyText(p.variableLabel(j))+" = "+number(c,c.result()->values[j])+(c.flags()[j]?" (integer)":" (continuous)"));html+="<h2>Original model</h2>";QStringList objective;for(std::size_t j=0;j<p.objective.size();++j)objective<<number(c,p.objective[j])+" * x"+QString::number(j+1);line((p.sense==lp::ObjectiveSense::Maximize?"Maximize: ":"Minimize: ")+objective.join(" + "));for(const auto& row:p.constraints){QStringList terms;for(std::size_t j=0;j<row.coefficients.size();++j)terms<<number(c,row.coefficients[j])+" * x"+QString::number(j+1);line(terms.join(" + ")+(row.relation==lp::Relation::LessEqual?" <= ":row.relation==lp::Relation::GreaterEqual?" >= ":" = ")+number(c,row.rhs));}for(std::size_t j=0;j<p.variables.size();++j){const auto& v=p.variables[j];line(legacyText(p.variableLabel(j))+": "+(v.unrestricted?QStringLiteral("unrestricted"):QStringLiteral("lower = %1; upper = %2").arg(number(c,v.lowerBound),std::isfinite(v.upperBound)?number(c,v.upperBound):QStringLiteral("infinity")))+(c.flags()[j]?"; integer":"; continuous"));}html+="<h2>Branch and bound trace</h2>";for(std::size_t i=0;i<c.result()->nodes.size();++i){const auto& node=c.result()->nodes[i];if(node.incoming)line("Defining branch: "+branchText(c,*node.incoming));line(QStringLiteral("Node %1; parent %2; depth %3; %4%5").arg(i+1).arg(node.parent?QString::number(*node.parent+1):"Root").arg(node.depth).arg(nodeState(node.state),node.bound?"; LP bound = "+number(c,*node.bound):QString()));if(node.branchVariable)line(QStringLiteral("Branch x%1 <= %2 or >= %3").arg(*node.branchVariable+1).arg(number(c,std::floor(node.branchValue)),number(c,std::ceil(node.branchValue))));QStringList point;for(std::size_t j=0;j<node.values.size();++j)point<<QStringLiteral("x%1 = %2").arg(j+1).arg(number(c,node.values[j]));if(!point.isEmpty())line(point.join("; "));}
 // Preserve the unsolved frontier in partial guided printouts without running LPs.
 if(c.guided()){
  const auto pending=c.guided()->pending();
  if(!pending.empty()){
   html+="<h2>Pending subproblems (LP relaxations not solved)</h2>";
   for(std::size_t i=0;i<pending.size();++i){
    const auto& node=pending[i];
    const auto metadata=QStringLiteral("Pending %1; parent %2; depth %3").arg(i+1).arg(node.parent?QString::number(*node.parent+1):"Root").arg(node.depth);
    QStringList path;
    if(node.incoming)path<<branchText(c,*node.incoming);
    auto parent=node.parent;
    while(parent){
     const auto& ancestor=c.result()->nodes[*parent];
     if(ancestor.incoming)path.prepend(branchText(c,*ancestor.incoming));
     parent=ancestor.parent;
    }
    line(metadata+". Defining branches: "+(path.isEmpty()?QStringLiteral("Root (original model)"):path.join("; "))+". Pending LP relaxation: not solved yet");
   }
  }
 }
 QTextDocument doc;doc.setDefaultFont(usableUiFont(font));auto option=doc.defaultTextOption();option.setWrapMode(QTextOption::WrapAtWordBoundaryOrAnywhere);doc.setDefaultTextOption(option);doc.setHtml(html);doc.print(&printer);return printer.printerState()!=QPrinter::Error && printer.printerState()!=QPrinter::Aborted;}catch(const std::exception&){return false;}}
